import {connectHUD} from './sdk-adapter.js';
function hudCurrent(){if(!activeRoute?.steps?.length)return ['walk_straight','0m','예제 경로를 선택하세요','',0,null,0,0];const step=activeRoute.steps[currentStepIdx];return [step.turnType,remainingStepDist+'m',step.instruction,step.subHint,currentSpeed,step.alertText,remainingTotalDist,Math.max(1,Math.ceil(remainingTotalDist/(currentMode==='walk'?75:600)))];}
function hudStep(delta){if(!activeRoute?.steps?.length)return;stopSimulation();currentStepIdx=Math.max(0,Math.min(activeRoute.steps.length-1,currentStepIdx+delta));remainingStepDist=activeRoute.steps[currentStepIdx].distMeter;remainingTotalDist=activeRoute.steps.slice(currentStepIdx).reduce((sum,step)=>sum+step.distMeter,0);renderStepsList();renderHUD(activeRoute.steps[currentStepIdx],remainingStepDist,currentSpeed,remainingTotalDist);}
const officialHUD=connectHUD({current:hudCurrent,render:renderGlassesHUDCanvas,next:()=>hudStep(1),previous:()=>hudStep(-1),stop:stopSimulation});
syncToGlasses=(...args)=>officialHUD.queue(args);
